import{_ as o,l as r,o as e,c as s,v as t,p as l,x as i,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"点-in-time 基本面对齐","description":"","frontmatter":{"title":"点-in-time 基本面对齐","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pit-alignment.md","filePath":"quant/pit-alignment.md","lastUpdated":1789023840000}'),c={name:"quant/pit-alignment.md"};function h(A,a,m,u,B,_){const n=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="点-in-time-基本面对齐" tabindex="-1">点-in-time 基本面对齐 <a class="header-anchor" href="#点-in-time-基本面对齐" aria-label="Permalink to &quot;点-in-time 基本面对齐&quot;">​</a></h1><div class="epigraph"><p>基本面因子与基本面风险模型要的不是「这一季的净资产是多少」，而是「在交易日 t，市场已经公开的、当时版本的净资产，能否与当日价格、股本、行业和成份对齐成同一条信息集」。</p><footer>—— 对照 Ljungqvist, Malloy and Marston, Rewriting History, Journal of Finance, 2009；Fama–French 账面滞后与 Asness–Frazzini 对 HML 时点的处理</footer></div><p><a href="/quant/backtest-overfitting">上一课</a>把报告最大值的原假设改成「整簇无技能」，有效试验次数由绩效相关结构决定。缺口从「试了多少次」转到「用的数字在 \\(t\\) 时是否存在」。<a href="/quant/point-in-time">时点基本面</a> 把单个字段的版本链说清；对齐是下一步：价格、股本、行业、成份、共识、风险暴露与会计字段来自不同供应商、不同日历。用财期结束日去 join 交易日，等于用未来报表算当时的因子。本课写 join 键、三套日历、以及错位如何同时污染 alpha 与风险归因。不重写 Reality Check 的自举。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一张可用的基本面观测至少有三个不相等的日期：<strong>财期结束日</strong>（这是哪一季）、<strong>首次披露日</strong>（file date / 公告日）、<strong>数据库可下载日</strong>（vendor available，常晚于交易所公告）。价格有交易日与成交时点；股本有除权日与登记日；行业有 GICS 生效日；成份有宣布日与生效日。合法的截面是：在调仓时点 \\(t\\)，所有输入都属于 \\(\\mathcal{F}_t\\)。错误的对齐通常不是缺 PIT 库，而是有 PIT 字段却用错了键——用 <code>fiscal_period_end</code> 去对 <code>trade_date</code>，于是 12 月 31 日的账面在 1 月 2 日就进了因子，而 10-K 要到三月才存在。</p><p>风险模型把问题放大。基本面暴露（账面市值、盈利、杠杆）若用事后更正的报表重算历史暴露，再拿去解释当时的收益，归因里会出现「当时市场不可能看到的因子」。Barra 一类模型的 vintage 必须与收益的起点对齐：用 \\(t\\) 日已知暴露解释 \\([t,t+h]\\) 的收益。用最终重述去拟合历史因子收益，样本内 \\(R^2\\) 会好看，组合的可交易残差却被说成特异风险。</p><h3 id="三套日历必须分开存、分开-join" tabindex="-1">三套日历必须分开存、分开 join <a class="header-anchor" href="#三套日历必须分开存、分开-join" aria-label="Permalink to &quot;三套日历必须分开存、分开 join&quot;">​</a></h3><p>不要把三个日期压成一列 <code>asof</code>。财期结束日只用于知道「这是 2022 年报还是 2023 一季报」；披露日用于可交易；供应商到达日用于生产回放（研究若用公告日、生产用供应商到达日，两边会系统性不一致）。分析师共识另有 vintage：公告前最后一个快照，不是月度文件里被事后改过的共识。Ljungqvist、Malloy 与 Marston（2009）表明推荐历史会被改写；没有快照，盈利意外的分母与分子都不在 \\(\\mathcal{F}_t\\)。</p><p><span class="marginnote">Worldscope、Compustat、国内研究库对「最新报表」的默认 join 不同。同一价值因子在 A 库显著、B 库不显著，经常是对齐键与更正政策不同，而不是市场不同。比较因子之前先比较 join。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>以披露日（或供应商到达日）为唯一 join 键。</strong> 回测日 \\(t\\) 的基本面行满足 <code>published_at ≤ t</code>，并取该约束下最新的一条。价格、股本用同一 \\(t\\) 的 PIT 快照。市值 $= $ 当时价 \\(\\times\\) 当时股本，分子用当时已知账面；拆股调整必须与当时已知的公司行为一致，不能把未来的复权因子提前除到历史上，否则低价过滤与每股指标会错，见 <a href="/quant/corporate-actions">公司行为</a>。</p><p><strong>统一滞后作为没有更正链时的下界。</strong> 没有 file date 时，季度数据至少滞后法定披露窗口（美股季报量级 40–60 天，年报更长；A 股年报多在 4 月 30 日前），Fama–French 把 \\(t-1\\) 年账面放到 \\(t\\) 年 6 月底，是对所有公司相同的可交易时点。Asness–Frazzini 主张每次新账面到达就更新 HML，仍然拒绝未公布数字。两种都是合法 PIT 规则；「数据库默认合并表」两条都不是。Hou、Xue 与 Zhang 的异象复制把滞后会计当成可投资性过滤，许多异象变弱——应读成对齐过滤，而不是单纯多重检验。</p><p><strong>风险模型 vintage。</strong> 每日（或每月）固化一套暴露：行业、风格、残差波动，全部带 <code>model_asof</code>。归因日 \\(t\\) 只用 <code>model_asof ≤ t</code> 的最近一套，去乘随后的收益。不得用期末重估的因子载荷回放全年。若供应商提供 restated 与 original 两套，研究与生产必须同一套；混合会让「风险模型解释力」变成修订过程的函数。</p><h3 id="公告日、交易时段与时区" tabindex="-1">公告日、交易时段与时区 <a class="header-anchor" href="#公告日、交易时段与时区" aria-label="Permalink to &quot;公告日、交易时段与时区&quot;">​</a></h3><p>美股常在盘前发布，A 股在非交易时段发布。PIT 的 \\(t\\) 应是「该信息可进入委托」的第一个时点，通常是下一撮合日开盘或收盘调仓点，而不是公告时间戳本身。财报与年报挤在同一窗口（A 股四月）会造成截面上大量名字同一天更新；对齐正确时这是真实的信息到达，不是 bug。错误的是用财期结束日把更新均匀摊到过去一个季度，让回测以为一月份已经有年报。</p><p><span class="marginnote">「用当时市值、用最新账面」是不对称泄漏：价格合法，分子非法。价值与盈利因子会被更正后的困境信息加强。两边都必须当时可知，join 才能叫对齐。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>错位通过两条通道进入损益。alpha 通道：latest-available 或财期键把未来减值、未来盈利提前写进「滞后」特征，样本内 IC 上升，实盘没有这些信息。风险通道：暴露用了未来报表，历史因子收益被错误归因，今日限额按一张不会在实盘出现的因子结构来切。两条通道可以同时发生：一个「低账面市值」组合既吃了前视的账面，又在风险模型里被当成价值暴露过小或过大，对冲比失真。</p><p>会计更正不是均值回归噪声。它往往在诉讼、审计变更、业绩变脸之后到来，与后续收益同向。因此错位不是随机测量误差，不能靠多一个因子、多一年样本平均掉。行业分类若用今天的 GICS 往回套，等于让过去的排序享受未来的行业地图；指数成份若用最终名单，见 <a href="/quant/survivorship-bias">幸存者偏差</a>。对齐的经济学含义是：因子与暴露必须是可交易信息的函数，否则测量的是数据库修订，不是风险补偿。</p><h3 id="点-in-time-对齐清单" tabindex="-1">点-in-time 对齐清单 <a class="header-anchor" href="#点-in-time-对齐清单" aria-label="Permalink to &quot;点-in-time 对齐清单&quot;">​</a></h3><p>每次构建截面，至少核对：\\((1)\\) 会计字段的 <code>published_at</code>；\\((2)\\) 价格与股本的交易日；\\((3)\\) 行业与成份的生效日是否 \\(\\le t\\)；\\((4)\\) 共识与实际 EPS 是否首次公布；\\((5)\\) 风险模型 <code>model_asof</code>；\\((6)\\) 研究与生产是否同一查询函数。缺任何一项，IC、IR、因子暴露与 <a href="/quant/var-methods">VaR</a> 的映射剩余都会被污染。映射若用错误时点的 beta 或基本面，基础风险看起来很小，只是因为泄漏把残差吸进了「因子」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>商业 PIT 库贵、早期更正链不完整、供应商到达日与交易所公告日可能差若干小时到若干天。用统一滞后是可发表的近似，应在能买到 PIT 的子样本上校准偏差方向：通常错误对齐让基本面因子更好看、让风险模型 \\(R^2\\) 更高。早期样本 file date 质量差时，宁可缩短样本，不要用财期结束日冒充披露日。</p><p>不要在对齐完成后，用全样本分位数把历史重新切成「当时的贵贱」——断点若用了未来截面，前视从字段层面回到排序层面。也不要在 NLP 文本、管理层指引上放弃时间戳：修订与转载同样会改写 \\(\\mathcal{F}_t\\)。生产若接「今日全量覆盖」接口、研究接 PIT，两边必须用 as-of 回放对齐，否则实盘暴露与回测暴露不是同一个随机向量。</p><p><span class="marginnote">对齐测试可以自动化：随机抽 \\(t\\)，把当日权重的全部依赖列成表，问每个字段在 \\(t\\) 是否可下载。凡是只能用 <code>fiscal_period_end</code> 对上的行，视为缺陷，而不是「数据不够所以将就」。</span></p>',25)),(e(),l(p,null,{default:i(()=>[E(n,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20FY%5B%22%E8%B4%A2%E6%9C%9F%E7%BB%93%E6%9D%9F%E6%97%A5%3A%20%E5%93%AA%E4%B8%80%E5%AD%A3%22%5D%20--%3E%20Row%5B%22%E5%9F%BA%E6%9C%AC%E9%9D%A2%E8%A1%8C%22%5D%0A%20%20FIL%5B%22%E6%8A%AB%E9%9C%B2%E6%97%A5%20published_at%22%5D%20--%3E%20Join%5B%22join%20%E9%94%AE%3A%20published_at%20%E2%89%A4%20t%22%5D%0A%20%20VEN%5B%22%E4%BE%9B%E5%BA%94%E5%95%86%E5%88%B0%E8%BE%BE%E6%97%A5%22%5D%20--%3E%20Join%0A%20%20PX%5B%22PIT%20%E4%BB%B7%E6%A0%BC%E4%B8%8E%E8%82%A1%E6%9C%AC%22%5D%20--%3E%20X%5B%22%E6%88%AA%E9%9D%A2%20X_t%22%5D%0A%20%20IND%5B%22PIT%20%E8%A1%8C%E4%B8%9A%E4%B8%8E%E6%88%90%E4%BB%BD%22%5D%20--%3E%20X%0A%20%20Join%20--%3E%20X%0A%20%20RM%5B%22%E9%A3%8E%E9%99%A9%E6%A8%A1%E5%9E%8B%20model_asof%20%E2%89%A4%20t%22%5D%20--%3E%20Exp%5B%22%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20X%20--%3E%20Fac%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E5%9B%A0%E5%AD%90%22%5D%0A%20%20X%20--%3E%20Exp%0A%20%20Bad%5B%22%E7%94%A8%E8%B4%A2%E6%9C%9F%E7%BB%93%E6%9D%9F%E6%97%A5%20join%22%5D%20--%3E%20LK%5B%22%E5%89%8D%E8%A7%86%E4%B8%8E%E9%94%99%E8%AF%AF%E5%BD%92%E5%9B%A0%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>点-in-time 对齐是多表在同一信息集 \\(\\mathcal{F}_t\\) 上的 join，键是披露日或供应商到达日，不是财期结束日。</li><li>价格、股本、行业、成份、共识与风险模型 vintage 必须与会计字段同一 as-of。</li><li>Fama–French 的六月滞后与 Asness–Frazzini 的及时更新是两种合法规则；数据库默认合并表不是。</li><li>错位同时抬高样本内 IC 与风险模型解释力，实盘两边都会坏。</li><li>出处：Ljungqvist, Malloy and Marston, <em>Journal of Finance</em>, 2009；Asness and Frazzini, <em>The Devil in HML’s Details</em>, 2013；Fama and French 账面滞后构造；Hou, Xue and Zhang, <em>Review of Financial Studies</em>, 2020。</li></ul>',2))])}const F=o(c,[["render",h]]);export{g as __pageData,F as default};
